const KEY='agrovantis-precision-v1';let db={clients:[],farms:[],fields:[]};let page='Painel',editing=null;const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=n=>Number(n).toLocaleString('pt-BR',{maximumFractionDigits:2});const names={Clientes:'clients',Propriedades:'farms',Talhões:'fields'};function parentName(id,list){return db[list].find(x=>x.id===id)?.name||'Sem vínculo'}function staticMap(fields){const pts=fields.flatMap(f=>f.rings?.flat()||[]);if(!pts.length)return '<div class="map"><div class="empty">Importe um KML para visualizar o limite do talhão.</div><span class="maplabel">Visualização dos limites · sem imagem de satélite</span></div>';let xs=pts.map(p=>p[0]),ys=pts.map(p=>p[1]),xmin=Math.min(...xs),ymin=Math.min(...ys),w=Math.max(...xs)-xmin||.001,h=Math.max(...ys)-ymin||.001;let scale=Math.min(520/w,300/h),ox=(600-w*scale)/2,oy=(360-h*scale)/2;return '<div class="map"><svg viewBox="0 0 600 360" role="img" aria-label="Limites dos talhões">'+fields.map(f=>'<path d="'+(f.rings||[]).map(r=>'M'+r.map(p=>(ox+(p[0]-xmin)*scale)+','+(360-oy-(p[1]-ymin)*scale)).join(' L')+' Z').join(' ')+'" fill="#81a75377" stroke="#3c6c35" stroke-width="2" fill-rule="evenodd"><title>'+esc(f.name)+' · '+fmt(f.area)+' ha</title></path>').join('')+'</svg><span class="maplabel">Limites georreferenciados · sem imagem de satélite</span></div>'}function render(){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#breadcrumb').textContent=page;$('#title').textContent=page==='Painel'?'Visão geral':page==='Talhões'?'Talhões e mapa':page==='Produtor'?'A propriedade na sua mão':page;$('#subtitle').textContent=page==='Produtor'?'Prévia de apresentação ao produtor. Esta tela não aplica permissões reais.':'Organize sua carteira e acompanhe os limites de cada talhão.';$('#add').hidden=!names[page]&&page!=='Painel';$('#add').textContent=page==='Propriedades'?'+ Nova propriedade':page==='Talhões'?'+ Novo talhão':'+ Novo cliente';let c=$('#content');if(page==='Amostragem'){renderSampling();return}if(page==='Painel'){c.innerHTML='<div class="cards">'+[['Clientes',db.clients.length,'Produtores cadastrados'],['Propriedades',db.farms.length,'Áreas acompanhadas'],['Área mapeada',fmt(db.fields.reduce((s,f)=>s+f.area,0))+' ha',db.fields.length+' talhões cadastrados']].map(x=>'<div class="card"><small>'+x[0]+'</small><strong>'+x[1]+'</strong><span>'+x[2]+'</span></div>').join('')+'</div><div class="grid"><div class="panel"><h2>Seu território de trabalho</h2>'+map(db.fields)+'</div><div class="panel"><h2>Comece sua carteira</h2>'+['Cadastre o produtor','Vincule uma propriedade','Importe os limites do talhão','Exporte uma cópia dos dados'].map((s,i)=>'<div class="step"><b>'+(i+1)+'</b>'+s+'</div>').join('')+'<p>Os módulos de amostragem e análise de solo serão desenvolvidos nas próximas etapas.</p><button id="export">Exportar dados</button></div></div>';$('#export').onclick=exportData;return}if(page==='Produtor'){c.innerHTML='<div class="panel"><h2>Prévia do portal</h2><p>Nenhum relatório técnico foi liberado nesta versão.</p>'+map(db.fields)+'<div class="step">'+db.farms.map(f=>esc(f.name)).join(' · ')+'</div></div>';return}c.innerHTML='<div class="toolbar"><input id="search" placeholder="Buscar por nome" aria-label="Buscar por nome"><button id="export">Exportar dados</button>'+(page==='Talhões'?'<label class="tag" style="margin:0">Importar KML<input id="kml" type="file" accept=".kml" style="max-width:230px"></label><select id="farmfilter" aria-label="Filtrar propriedade"><option value="">Todas as propriedades</option>'+db.farms.map(f=>'<option value="'+f.id+'">'+esc(f.name)+'</option>').join('')+'</select>':'')+'</div><div class="panel" id="listing"></div>';$('#search').oninput=list;$('#export').onclick=exportData;if(page==='Talhões'){$('#farmfilter').onchange=list;$('#kml').onchange=importKml}list()}function list(){let items=db[names[page]].filter(x=>x.name.toLowerCase().includes($('#search').value.toLowerCase())&&(page!=='Talhões'||!$('#farmfilter').value||x.farmId===$('#farmfilter').value));$('#listing').innerHTML=(page==='Talhões'?map(items):'')+'<table><thead><tr><th>Nome</th><th>'+({Clientes:'Contato',Propriedades:'Produtor',Talhões:'Propriedade'})[page]+'</th><th>'+({Clientes:'E-mail',Propriedades:'Município',Talhões:'Área (ha)'})[page]+'</th><th>Ações</th></tr></thead><tbody>'+items.map(x=>'<tr><td><b>'+esc(x.name)+'</b></td><td>'+esc(page==='Clientes'?x.contact:parentName(page==='Propriedades'?x.clientId:x.farmId,page==='Propriedades'?'clients':'farms'))+'</td><td>'+esc(page==='Clientes'?x.email:page==='Propriedades'?x.city:fmt(x.area))+'</td><td><button data-edit="'+x.id+'">Editar</button> <button data-delete="'+x.id+'">Excluir</button></td></tr>').join('')+'</tbody></table>'+(!items.length?'<div class="empty">Nenhum cadastro encontrado. Comece pelo botão acima.</div>':'');document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openForm(b.dataset.edit));document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=async()=>{let id=b.dataset.delete;if(page==='Clientes'&&db.farms.some(f=>f.clientId===id)||page==='Propriedades'&&db.fields.some(f=>f.farmId===id)){alert('Remova os cadastros vinculados antes de excluir.');return}if(confirm('Excluir este cadastro?')){try{await cloudDelete(names[page],id);await loadData()}catch(e){alert(e.message)}}})}function field(label,name,value='',type='text'){return '<label>'+label+'<input required name="'+name+'" type="'+type+'" value="'+esc(value)+'"></label>'}function select(label,name,list,value){return '<label>'+label+'<select required name="'+name+'"><option value="">Selecione</option>'+db[list].map(x=>'<option value="'+x.id+'" '+(value===x.id?'selected':'')+'>'+esc(x.name)+'</option>').join('')+'</select></label>'}function openForm(id){if(page==='Painel')page='Clientes';editing=id;let x=db[names[page]].find(x=>x.id===id)||{};$('#formtitle').textContent=(id?'Editar':'Novo')+' cadastro';$('#error').textContent='';$('#inputs').innerHTML=field('Nome','name',x.name)+(page==='Clientes'?field('Contato','contact',x.contact)+field('E-mail','email',x.email,'email'):page==='Propriedades'?select('Produtor','clientId','clients',x.clientId)+field('Município / UF','city',x.city):select('Propriedade','farmId','farms',x.farmId)+field('Área declarada (ha)','area',x.area||'','number'));if(page==='Talhões'){$('[name=area]').setAttribute('step','0.0001');if(x.rings)$('[name=area]').readOnly=true;}$('#modal').showModal()}$('#form').onsubmit=async e=>{e.preventDefault();let data=Object.fromEntries(new FormData(e.target));data.name=data.name.trim();if(!data.name){$('#error').textContent='Informe um nome.';return}let rows=db[names[page]],old=rows.find(x=>x.id===editing);if(page==='Talhões'){data.area=Number(data.area);if(!(data.area>0)){$('#error').textContent='Informe uma área maior que zero.';return}if(old?.rings){data.area=old.area;data.rings=old.rings}}try{await cloudWrite(names[page],{...data,id:old?.id||crypto.randomUUID()},!!old);$('#modal').close();await loadData()}catch(err){$('#error').textContent=err.message}};$('#close').onclick=()=>$('#modal').close();$('#add').onclick=()=>openForm();document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{page=b.dataset.page;render()});function exportData(){let a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(db,null,2)],{type:'application/json'}));a.href=url;a.download='agrovantis-precision-dados.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}function areaRing(r){let sum=0;for(let i=0;i<r.length;i++){let a=r[i],b=r[(i+1)%r.length];sum+=(b[0]-a[0])*Math.PI/180*(2+Math.sin(a[1]*Math.PI/180)+Math.sin(b[1]*Math.PI/180))}return Math.abs(sum*6371008.8**2/2)/10000}async function importKml(e){let file=e.target.files[0];if(!file)return;let farmId=$('#farmfilter').value;if(!farmId){alert('Selecione a propriedade de destino no filtro antes de importar.');e.target.value='';return}try{if(file.size>5e6)throw Error('O arquivo deve ter até 5 MB.');let xml=new DOMParser().parseFromString(await file.text(),'application/xml');if(xml.querySelector('parsererror'))throw Error('Arquivo KML inválido.');let added=[];for(let pm of xml.getElementsByTagNameNS('*','Placemark')){let name=pm.getElementsByTagNameNS('*','name')[0]?.textContent||file.name;for(let poly of pm.getElementsByTagNameNS('*','Polygon')){let rings=Array.from(poly.getElementsByTagNameNS('*','coordinates')).map(c=>c.textContent.trim().split(/\s+/).map(s=>s.split(',').slice(0,2).map(Number)));if(rings.some(r=>r.length<4||r.some(p=>p.length!==2||!p.every(Number.isFinite)||Math.abs(p[0])>180||Math.abs(p[1])>90)))throw Error('Coordenadas inválidas no polígono.');let area=areaRing(rings[0])-rings.slice(1).reduce((s,r)=>s+areaRing(r),0);if(!(area>0))throw Error('Polígono sem área válida.');added.push({id:crypto.randomUUID(),farmId,name,rings,area})}}if(!added.length)throw Error('O KML não contém polígonos.');for(const row of added)await cloudWrite('fields',row);await loadData();alert(added.length+' talhão(ões) importado(s). A área é uma estimativa esférica; confira antes do uso técnico.')}catch(err){alert(err.message)}e.target.value=''}boot();
